-- V105__seed_sportline.sql — Sportline (www.sportline.com.ar), VTEX: seed plus the curated leaf mapping of its accessories.
--
-- Measured 2026-11-19 (legacy API, header `resources`): 6915 products, 6918 in a real scrape (11.5 min); tree/3 =
-- MUJER / HOMBRE / NIÑOS / BEBES / UNISEX (734 nodes, the same leaf repeated under each gender) and DEPORTES.
-- Multibrand sports retailer, like Sporting: rubro_forzado stays NULL and there is no rubro_por_defecto, so RubroResolver
-- decides by category (apparel and footwear = indumentaria, balls/rackets/weights = deporte).
--
-- Leaf mapping: no new categories. The name classifier is already right on apparel and footwear (Otros was 110 of 6918);
-- what it abstained on were the ACCESORIOS leaves (mouth guards, hockey sticks, rackets, jump ropes, mats, whistles...),
-- mapped here by leaf name under every gender. Left unmapped on purpose: ROPA INTERIOR (8 rows, no canonical category).
-- One single-line text blob (sitio_key|origen_id|nombre|categoria rows joined by ';', no raw newline: Sonar flags one inside a literal) split by the INSERT, not a literal per row: a string repeated
-- three times is Sonar S1192, and a long VALUES list of near-identical tuples is what Sonar CPD reads as duplicated code.
INSERT INTO sitio (nombre, sitio_key, plataforma, es_premium, rubro_forzado, origen) VALUES
    ('Sportline', 'sportline', 'vtex', false, NULL, 'config')
ON CONFLICT (nombre) DO NOTHING;

WITH linea(l) AS (SELECT regexp_split_to_table('sportline|1000041|BOTINEROS|Bolso;sportline|1000042|BOTINEROS|Bolso;sportline|1000043|BOTINEROS|Bolso;sportline|1000080|GIMNASIOS|Accesorio de Fitness;sportline|1000081|GIMNASIOS|Accesorio de Fitness;sportline|1000082|GIMNASIOS|Accesorio de Fitness;sportline|1000095|INFLADORES - PICOS|Equipamiento Deportivo;sportline|1000096|INFLADORES - PICOS|Equipamiento Deportivo;sportline|1000097|INFLADORES - PICOS|Equipamiento Deportivo;sportline|1000119|PALOS HOCKEY|Equipamiento Deportivo;sportline|1000120|PALOS HOCKEY|Equipamiento Deportivo;sportline|1000121|PALOS HOCKEY|Equipamiento Deportivo;sportline|1000131|PROTECTORES|Equipamiento Deportivo;sportline|1000132|PROTECTORES|Equipamiento Deportivo;sportline|1000133|PROTECTORES|Equipamiento Deportivo;sportline|1000228|CORDONES|Accesorio Deportivo;sportline|1000229|CORDONES|Accesorio Deportivo;sportline|1000230|CORDONES|Accesorio Deportivo;sportline|1000237|GRIPS|Equipamiento Deportivo;sportline|1000238|GRIPS|Equipamiento Deportivo;sportline|1000239|GRIPS|Equipamiento Deportivo;sportline|1000249|SILBATOS|Equipamiento Deportivo;sportline|1000250|SILBATOS|Equipamiento Deportivo;sportline|1000251|SILBATOS|Equipamiento Deportivo;sportline|1000258|ESPUMAS|Accesorio Deportivo;sportline|1000259|ESPUMAS|Accesorio Deportivo;sportline|1000260|ESPUMAS|Accesorio Deportivo;sportline|1000282|TAPÓN DE OÍDO|Equipamiento Deportivo;sportline|1000283|TAPÓN DE OÍDO|Equipamiento Deportivo;sportline|1000284|TAPÓN DE OÍDO|Equipamiento Deportivo;sportline|1000285|TAPÓN DE NARIZ|Equipamiento Deportivo;sportline|1000286|TAPÓN DE NARIZ|Equipamiento Deportivo;sportline|1000287|TAPÓN DE NARIZ|Equipamiento Deportivo;sportline|1000303|SOGA DE SALTAR|Accesorio de Fitness;sportline|1000304|SOGA DE SALTAR|Accesorio de Fitness;sportline|1000305|SOGA DE SALTAR|Accesorio de Fitness;sportline|1000312|TAPIS DE YOGA|Accesorio de Fitness;sportline|1000313|TAPIS DE YOGA|Accesorio de Fitness;sportline|1000314|TAPIS DE YOGA|Accesorio de Fitness;sportline|1000318|BOCHA|Equipamiento Deportivo;sportline|1000319|BOCHA|Equipamiento Deportivo;sportline|1000320|BOCHA|Equipamiento Deportivo;sportline|1000350|BOCHA|Equipamiento Deportivo;sportline|1000353|BOTINEROS|Bolso;sportline|1000360|CORDONES|Accesorio Deportivo;sportline|1000365|ESPUMAS|Accesorio Deportivo;sportline|1000367|GIMNASIOS|Accesorio de Fitness;sportline|1000370|GRIPS|Equipamiento Deportivo;sportline|1000374|INFLADORES - PICOS|Equipamiento Deportivo;sportline|1000386|PALOS HOCKEY|Equipamiento Deportivo;sportline|1000391|PROTECTORES|Equipamiento Deportivo;sportline|1000399|SILBATOS|Equipamiento Deportivo;sportline|1000402|SOGA DE SALTAR|Accesorio de Fitness;sportline|1000405|TAPIS DE YOGA|Accesorio de Fitness;sportline|1000406|TAPÓN DE NARIZ|Equipamiento Deportivo;sportline|1000407|TAPÓN DE OÍDO|Equipamiento Deportivo;sportline|1000418|BOCHA|Equipamiento Deportivo;sportline|1000421|BOTINEROS|Bolso;sportline|1000425|CINTAS|Accesorio de Fitness;sportline|1000428|CORDONES|Accesorio Deportivo;sportline|1000433|ESPUMAS|Accesorio Deportivo;sportline|1000435|GIMNASIOS|Accesorio de Fitness;sportline|1000438|GRIPS|Equipamiento Deportivo;sportline|1000442|INFLADORES - PICOS|Equipamiento Deportivo;sportline|1000454|PALOS HOCKEY|Equipamiento Deportivo;sportline|1000459|PROTECTORES|Equipamiento Deportivo;sportline|1000467|SILBATOS|Equipamiento Deportivo;sportline|1000469|SOGA DE SALTAR|Accesorio de Fitness;sportline|1000471|TAPIS DE YOGA|Accesorio de Fitness;sportline|1000472|TAPÓN DE NARIZ|Equipamiento Deportivo;sportline|1000473|TAPÓN DE OÍDO|Equipamiento Deportivo;sportline|1000711|FITNESS|Accesorio de Fitness;sportline|1000712|FITNESS|Accesorio de Fitness;sportline|1000713|FITNESS|Accesorio de Fitness;sportline|1000714|FITNESS|Accesorio de Fitness;sportline|1000715|FITNESS|Accesorio de Fitness;sportline|1000726|MUSCULACION|Pesas;sportline|1000727|MUSCULACION|Pesas;sportline|1000728|MUSCULACION|Pesas;sportline|1000729|MUSCULACION|Pesas;sportline|1000730|MUSCULACION|Pesas;sportline|1000743|RAQUETAS|Equipamiento Deportivo;sportline|1000744|RAQUETAS|Equipamiento Deportivo;sportline|1000745|RAQUETAS|Equipamiento Deportivo;sportline|1000746|RAQUETAS|Equipamiento Deportivo;sportline|1000747|RAQUETAS|Equipamiento Deportivo;sportline|1000752|TAPÓN DE NARIZ|Equipamiento Deportivo;sportline|1000753|TAPÓN DE NARIZ|Equipamiento Deportivo;sportline|1000754|TAPÓN DE OÍDO|Equipamiento Deportivo;sportline|1000755|TAPÓN DE OÍDO|Equipamiento Deportivo', ';')),
campo(f) AS (SELECT string_to_array(l, '|') FROM linea)
INSERT INTO sitio_categoria (sitio_key, origen_id, nombre, categoria)
SELECT f[1], f[2]::int, f[3], f[4] FROM campo
ON CONFLICT (sitio_key, origen_id) DO UPDATE SET categoria = EXCLUDED.categoria;
